import java.io.BufferedReader
import java.io.InputStreamReader
import kotlin.math.max
import kotlin.math.min
import kotlin.math.ceil

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val (HPY, ATKY, DEFY) = br.readLine().trim().split(" ").map { it.toInt() }
    val (HPM, ATKM, DEFM) = br.readLine().trim().split(" ").map { it.toInt() }
    val (h, a, d) = br.readLine().trim().split(" ").map { it.toInt() }

    var answer = Int.MAX_VALUE

    // Upper bounds for search
    val maxAtkY = 200    // ATKY + extraAtk up to 200
    val maxDefY = 200    // DEFY + extraDef up to 200

    for (atkY in ATKY..maxAtkY) {
        val dmgToMonster = max(0, atkY - DEFM)
        if (dmgToMonster == 0) continue

        for (defY in DEFY..maxDefY) {
            val dmgToYang = max(0, ATKM - defY)

            // Yang must survive until monster dies
            val turnsToKillMonster = ceil(HPM.toDouble() / dmgToMonster).toInt()
            val requiredHPY = if (dmgToYang == 0) 1 else dmgToYang * (turnsToKillMonster - 1) + 1

            val extraHP = max(0, requiredHPY - HPY)
            val extraAtk = atkY - ATKY
            val extraDef = defY - DEFY

            val cost = extraHP * h + extraAtk * a + extraDef * d
            answer = min(answer, cost)
        }
    }

    println(answer)
}

import java.io.BufferedReader
import java.io.InputStreamReader
import kotlin.math.max
import kotlin.math.min
import kotlin.math.ceil

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val (hpY0, atkY0, defY0) = br.readLine().trim().split(" ").map { it.toInt() }
    val (hpM, atkM, defM) = br.readLine().trim().split(" ").map { it.toInt() }
    val (hCost, aCost, dCost) = br.readLine().trim().split(" ").map { it.toInt() }

    var answer = Int.MAX_VALUE

    // Upper bounds chosen safely large
    for (atkY in atkY0..200) {
        val dmgToMonster = max(0, atkY - defM)
        if (dmgToMonster == 0) continue

        for (defY in defY0..200) {
            val dmgToYang = max(0, atkM - defY)

            // Rounds needed to kill monster
            val roundsToKill = (hpM + dmgToMonster - 1) / dmgToMonster

            val neededHp = if (dmgToYang == 0) 1 else dmgToYang * (roundsToKill - 1) + 1
            val extraHp = max(0, neededHp - hpY0)

            val cost = (atkY - atkY0) * aCost +
                       (defY - defY0) * dCost +
                       extraHp * hCost

            answer = min(answer, cost)
        }
    }

    println(answer)
}
